const mediaGrantSql=(photoAlias,userRef)=>`(EXISTS(SELECT 1 FROM user_browse_cycle_state cycle JOIN user_browse_cycle_photos unlocked ON unlocked.user_id=cycle.user_id AND unlocked.cycle_no=cycle.cycle_no WHERE cycle.user_id=${userRef} AND unlocked.photo_id=${photoAlias}.id) OR EXISTS(SELECT 1 FROM photo_annotations completed WHERE completed.photo_id=${photoAlias}.id AND completed.status='complete' AND completed.completed_by=${userRef}) OR EXISTS(SELECT 1 FROM restricted_annotation_focus focus WHERE focus.user_id=${userRef} AND focus.photo_id=${photoAlias}.id) OR EXISTS(SELECT 1 FROM annotation_tasks task WHERE task.assigned_to=${userRef} AND task.photo_id=${photoAlias}.id AND task.status='assigned'))`;
function photoPublic(row,user){return{id:row.id,bird:row.individual_id,filename:row.filename,captureTime:iso(row.capture_time),lat:row.latitude==null?null:Number(row.latitude),lon:row.longitude==null?null:Number(row.longitude),gpsTime:iso(row.gps_time),locationSource:row.location_source||null,altitudeM:row.altitude_m==null?null:Number(row.altitude_m),elevationM:row.elevation_m==null?null:Number(row.elevation_m),mediaGranted:!!row.media_granted,imageUrl:imageUrl(row.id,user),previewUrl:imageUrl(row.id,user,true)};}
function photoJoined(row,user){return{...photoPublic(row,user),address:row.address,country:row.country,closeCity:row.close_city,geoDescription:row.geo_desc,filePath:row.source_url||row.original_path||row.storage_path||null,mimeType:row.mime_type,sizeBytes:row.size_bytes==null?null:Number(row.size_bytes),sha256:row.sha256,mediaStatus:row.media_status,sourceRow:row.source_row,status:row.status||"unstarted",version:Number(row.version||0),annotation:fromDbAnnotation(row),photoCreatedAt:iso(row.photo_created_at||row.created_at),photoUpdatedAt:iso(row.photo_updated_at||row.updated_at),updatedAt:iso(row.annotation_updated_at),updatedBy:row.updated_by_name?{id:row.updated_by,name:row.updated_by_name}:null,canEdit:row.can_edit===undefined?null:!!row.can_edit,isMine:row.is_mine===undefined?null:!!row.is_mine};}
function safeStorage(storagePath){if(!storagePath)return null;const absolute=path.resolve(photoDir,storagePath),rel=path.relative(photoDir,absolute);return rel.startsWith("..")||path.isAbsolute(rel)?null:absolute;}
async function resolveUploadedPhotoLocation(individualId,captureTime,exif){
  if(exif.hasGps)return{latitude:exif.latitude,longitude:exif.longitude,gpsTime:exif.gpsTime||captureTime||null,altitudeM:exif.altitudeM,locationSource:"exif"};
  if(!captureTime)return{latitude:null,longitude:null,gpsTime:null,altitudeM:null,locationSource:"missing"};
  const padding=photoGpsMaxOffsetMinutes*60,result=await db.query(`SELECT observed_at,longitude,latitude,altitude_m FROM gps_points WHERE individual_id=$1 AND observed_at BETWEEN $2::timestamptz-($3::double precision*interval '1 second') AND $2::timestamptz+($3::double precision*interval '1 second') ORDER BY abs(extract(epoch FROM observed_at-$2::timestamptz)) LIMIT 2`,[individualId,captureTime,padding]),points=result.rows.map((row)=>({observedAt:row.observed_at,lon:Number(row.longitude),lat:Number(row.latitude),altitudeM:row.altitude_m==null?null:Number(row.altitude_m)})),fallback=nearestTrackPoint(points,captureTime,photoGpsMaxOffsetMinutes);
  return fallback?{latitude:fallback.lat,longitude:fallback.lon,gpsTime:fallback.observedAt,altitudeM:fallback.altitudeM,locationSource:"track"}:{latitude:null,longitude:null,gpsTime:null,altitudeM:null,locationSource:"missing"};
}

async function servePhoto(req,res,next,publicOnly=true){try{
  const result=await db.query(`SELECT id,storage_path,mime_type,sha256,public_visible,media_status FROM photos WHERE id=$1 ${publicOnly?"AND public_visible=true":""}`,[req.params.id]);
  const photo=result.rows[0]; if(!photo||photo.media_status!=="available")return res.status(404).json({error:"photo_not_found"});
  const original=safeStorage(photo.storage_path); if(!original||!fs.existsSync(original))return res.status(404).json({error:"photo_file_missing"});
  const stat=fs.statSync(original),etag=`\"${photo.sha256||`${photo.id}-${stat.size}`}\"`; if(req.headers["if-none-match"]===etag)return res.status(304).end();
  res.setHeader("ETag",etag);res.setHeader("Cache-Control","private, max-age=900, no-transform");
  if(req.query.kind!=="preview")return sendOriginalPhoto(res,next,{file:original,mimeType:photo.mime_type||"image/jpeg"});
  const preview=path.join(previewDir,`${photo.id}.webp`);
  return sendPreviewOrOriginal(res,next,{original,originalMimeType:photo.mime_type||"image/jpeg",preview,createPreview:(temporary)=>sharp(original).rotate().resize({width:720,height:720,fit:"inside",withoutEnlargement:true}).webp({quality:78}).toFile(temporary),onFallback:(error)=>console.warn(`Preview unavailable for ${photo.id}; serving original.`,error.message)});
}catch(error){next(error);}}

async function authorizeMediaAndServe(req,res,next){try{const access=await transaction((client)=>ensurePhotoAccess(client,req.user,req.params.id,{purpose:"browse"}));if(!access.allowed)return res.status(access.http||403).json({error:access.error,contribution:access.profile||null});return servePhoto(req,res,next,false);}catch(error){next(error);}}

