function mailTransport(){return process.env.SMTP_HOST?nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:String(process.env.SMTP_SECURE||"false")==="true",auth:process.env.SMTP_USER?{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}:undefined}):null;}
function roleDescription(role){return{admin:{label:"Administrator",permissions:"może zarządzać użytkownikami, importować dane oraz przeglądać, edytować, eksportować i moderować wszystkie rekordy."},coordinator:{label:"Koordynator",permissions:"może przeglądać i edytować wszystkie rekordy, eksportować dane, obsługiwać weryfikację i moderować kategorie, ale nie zarządza użytkownikami ani importem."},annotator:{label:"Użytkownik",permissions:"może przeglądać wszystkie rekordy, edytować własne i rozpoczynać nieopisane rekordy przypisanych osobników, a także używać ocen, prywatnego sejfu zdjęć i zgłoszeń do weryfikacji."}}[role]||{label:role,permissions:"dostęp zgodny z ustawieniami konta."};}
function inviteMessage(user,password,profile=null){
  const subject="Zaproszenie do Stork Photo Editor",role=roleDescription(user.role),restricted=user.role==="annotator"&&!!user.restricted_contributor,settings=profile?.settings||{},allowance=settings.initialBrowsingAllowance??30,bestThreshold=settings.bestPicturesThreshold??50,fullThreshold=settings.fullAccessThreshold??400;
  const accessDescription=restricted?["Tryb konta: Restricted Contributor.","Zasady dostępu:",`- W każdym cyklu możesz odkryć maksymalnie ${allowance} nowych zwykłych zdjęć. Ponowne otwarcie zdjęcia z bieżącego cyklu nie zużywa kolejnego miejsca.`,`- Po wykorzystaniu puli wybierz Start annotating. Ukończenie jednego rekordu jako complete rozpoczyna nowy cykl z pulą ${allowance} zdjęć.`,"- Zdjęcia ukończone przez Ciebie pozostają zawsze dostępne i nie zużywają bieżącej puli.",`- Prywatny sejf zdjęć odblokuje się po ${bestThreshold} ukończonych adnotacjach.`,`- Pełny dostęp do kolekcji odblokuje się po ${fullThreshold} ukończonych adnotacjach.`,"- Limity są chronione przez serwer i obowiązują również przy filtrach, tabeli oraz bezpośrednich adresach zdjęć."]:[];
  const body=[`Witaj ${user.name},`,"","Masz konto w aplikacji Stork Photo Editor.","",`Aplikacja: ${publicAppUrl}`,`Email: ${user.email}`,`Twoja rola: ${role.label}.`,`Uprawnienia: ${restricted?"możesz opisywać przydzielone zdjęcia i stopniowo odblokowywać dostęp przez ukończone adnotacje.":role.permissions}`,...(accessDescription.length?["",...accessDescription]:[]),"",`Hasło tymczasowe: ${password}`,"","Po pierwszym logowaniu trzeba zmienić hasło.","","Instrukcja:","1. Otwórz aplikację.","2. Zaloguj się emailem i hasłem tymczasowym.","3. Ustaw własne hasło.","4. Rozpocznij pracę z przydzielonymi zdjęciami.","","Stork Photo Editor"].join("\n"),params=new URLSearchParams({view:"cm",fs:"1",to:user.email,su:subject,body});return{subject,body,gmailUrl:`https://mail.google.com/mail/?${params}`,mailtoUrl:`mailto:${encodeURIComponent(user.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`};
}
async function invite(user,password){const profile=user.role==="annotator"&&user.restricted_contributor?await contributionForUser(db,user):null,message=inviteMessage(user,password,profile),transport=mailTransport();if(!transport)return{sent:false,temporaryPassword:password,gmailUrl:message.gmailUrl,mailtoUrl:message.mailtoUrl,reason:"smtp_not_configured"};try{await transport.sendMail({from:process.env.MAIL_FROM||"Stork Photo Editor <noreply@example.com>",to:user.email,subject:message.subject,text:message.body});return{sent:true};}catch(error){console.error(`Invitation email failed for ${user.email}.`,error);return{sent:false,temporaryPassword:password,gmailUrl:message.gmailUrl,mailtoUrl:message.mailtoUrl,reason:"smtp_send_failed"};}}
