app.post("/api/annotation-options",authenticateUser,writeLimiter,async(req,res,next)=>{try{
  const fieldKey=String(req.body.fieldKey||"").trim(),value=String(req.body.value||"").replaceAll("\0","").trim(),reason=String(req.body.reason||"").replaceAll("\0","").trim();
  if(!EXTENSIBLE_ANNOTATION_FIELDS.includes(fieldKey))return res.status(400).json({error:"field_is_not_extensible"});
  if(!value||value.length>100)return res.status(400).json({error:"invalid_option_value"});
  const approved=["admin","coordinator"].includes(req.user.role);if(!approved&&(!reason||reason.length>500))return res.status(400).json({error:"category_reason_required"});
  const row=(await db.query("INSERT INTO annotation_options(field_key,value,created_by,status,reason,reviewed_by,reviewed_at) VALUES($1,$2,$3,$4,$5,$6,CASE WHEN $4='approved' THEN now() ELSE NULL END) ON CONFLICT(field_key,value) DO UPDATE SET reason=EXCLUDED.reason,status=CASE WHEN annotation_options.status='approved' THEN 'approved' ELSE EXCLUDED.status END RETURNING field_key,value,status,reason",[fieldKey,value,req.user.id,approved?"approved":"pending",reason||null,approved?req.user.id:null])).rows[0];await audit(req.user,approved?"annotation_option_added":"annotation_option_proposed","annotation_option",`${fieldKey}:${value}`,{reason:reason||null},req);res.status(201).json({fieldKey:row.field_key,value:row.value,status:row.status,reason:row.reason});
}catch(e){next(e);}});
