app.post("/api/photos/:id/access",authenticateUser,writeLimiter,async(req,res,next)=>{try{const purpose=String(req.body.purpose||"browse");if(!["browse","annotation"].includes(purpose))return res.status(400).json({error:"invalid_access_purpose"});const result=await transaction(async(client)=>{let effectivePurpose="browse";if(purpose==="annotation"){const photo=(await client.query("SELECT * FROM photos WHERE id=$1",[req.params.id])).rows[0];if(!photo)return{allowed:false,http:404,error:"photo_not_found"};const current=(await client.query("SELECT * FROM photo_annotations WHERE photo_id=$1",[photo.id])).rows[0]||null;if(!await annotationPermission(req.user,photo,current,client))return{allowed:false,http:403,error:"annotation_read_only"};const taskAssigned=!!(await client.query("SELECT 1 FROM annotation_tasks WHERE assigned_to=$1 AND photo_id=$2 AND status='assigned'",[req.user.id,photo.id])).rows[0],focusActive=!!(await client.query("SELECT 1 FROM restricted_annotation_focus WHERE user_id=$1 AND photo_id=$2",[req.user.id,photo.id])).rows[0],ownCompleted=current?.status==="complete"&&current.completed_by===req.user.id,profile=await contributionForUser(client,req.user);if(profile.restricted&&profile.browseLimitReached&&!taskAssigned&&!focusActive&&!ownCompleted)return{allowed:false,http:403,error:"browsing_limit_reached",profile};effectivePurpose=taskAssigned||focusActive?"annotation":"browse";}return ensurePhotoAccess(client,req.user,req.params.id,{purpose:effectivePurpose});});if(!result.allowed)return res.status(result.http||403).json({error:result.error,contribution:result.profile||null});const photo=(await db.query("SELECT * FROM photos WHERE id=$1",[req.params.id])).rows[0];res.json({ok:true,photo:photoPublic({...photo,media_granted:true},req.user),contribution:result.profile});}catch(e){next(e);}});
