app.get("/api/me/photo-collection",authenticateUser,async(req,res,next)=>{try{const profile=await contributionForUser(db,req.user);if(!profile.bestPicturesUnlocked)return res.status(403).json({error:"best_pictures_locked",contribution:profile});const collection=String(req.query.collection||"favorites"),sort=String(req.query.sort||"rating_desc"),access=accessSql(req.user,"p.individual_id",2),params=[req.user.id,...access.params],where=[access.sql];if(collection==="favorites")where.push("f.user_id=$1");else if(collection==="rated")where.push("stats.rating_count>0");else return res.status(400).json({error:"invalid_collection"});const order=sort==="date_desc"?"p.capture_time DESC NULLS LAST":sort==="date_asc"?"p.capture_time NULLS LAST":"stats.average_rating DESC NULLS LAST,p.capture_time DESC NULLS LAST";const rows=(await db.query(`SELECT p.*,f.user_id IS NOT NULL favorite,own.rating own_rating,stats.average_rating,stats.rating_count,${mediaGrantSql("p","$1")} media_granted FROM photos p LEFT JOIN user_photo_favorites f ON f.photo_id=p.id AND f.user_id=$1 LEFT JOIN photo_ratings own ON own.photo_id=p.id AND own.user_id=$1 LEFT JOIN (SELECT photo_id,avg(rating) average_rating,count(*) rating_count FROM photo_ratings GROUP BY photo_id) stats ON stats.photo_id=p.id WHERE ${where.join(" AND ")} ORDER BY ${order} LIMIT 1000`,params)).rows;res.json({photos:rows.map((row)=>({...photoPublic(row,req.user),social:photoSocial(row)})),contribution:profile});}catch(e){next(e);}});

app.get("/api/me/photo-collection/download",authenticateUser,async(req,res,next)=>{try{
  const profile=await contributionForUser(db,req.user);if(!profile.bestPicturesUnlocked)return res.status(403).json({error:"photo_safe_locked",contribution:profile});
  const collection=String(req.query.collection||"rated");let rows,downloadName,auditAction,auditDetails;
  if(collection==="favorites"){
    rows=(await db.query(`SELECT p.* FROM user_photo_favorites f JOIN photos p ON p.id=f.photo_id WHERE f.user_id=$1 AND p.media_status='available' ORDER BY f.created_at DESC LIMIT 1000`,[req.user.id])).rows;
    downloadName="my-photo-safe.zip";auditAction="photo_safe_downloaded";auditDetails={count:rows.length};
  }else if(collection==="rated"){
    const minimumRating=Math.max(1,Math.min(5,Number(req.query.minimumRating)||4));
    rows=(await db.query(`SELECT p.* FROM photos p JOIN (SELECT photo_id,avg(rating) average_rating FROM photo_ratings GROUP BY photo_id HAVING avg(rating)>=$1) rated ON rated.photo_id=p.id WHERE p.media_status='available' ORDER BY rated.average_rating DESC,p.capture_time DESC NULLS LAST LIMIT 1000`,[minimumRating])).rows;
    downloadName=`top-rated-${String(minimumRating).replace(".","-")}.zip`;auditAction="rated_photos_downloaded";auditDetails={minimumRating,count:rows.length};
  }else return res.status(400).json({error:"invalid_collection"});
  if(!rows.length)return res.status(404).json({error:collection==="favorites"?"photo_safe_empty":"no_photos_for_rating_threshold"});
  try{await transaction(async(client)=>{for(const row of rows){const access=await ensurePhotoAccess(client,req.user,row.id,{purpose:"browse"});if(!access.allowed){const error=new Error(access.error);error.http=access.http||403;error.profile=access.profile;throw error;}}});}catch(error){if(error.message==="browsing_limit_reached")return res.status(error.http||403).json({error:error.message,contribution:error.profile||null});throw error;}
  await audit(req.user,auditAction,"photo_collection",null,auditDetails,req);return sendZip(res,rows,[],photoDir,downloadName);
}catch(e){next(e);}});

app.post("/api/photos/:id/review-requests",authenticateUser,writeLimiter,async(req,res,next)=>{try{const fieldKey=normalizeReviewField(req.body.fieldKey),reason=String(req.body.reason||"").replaceAll("\0","").trim(),photo=(await db.query("SELECT individual_id FROM photos WHERE id=$1",[req.params.id])).rows[0];if(!photo)return res.status(404).json({error:"photo_not_found"});if(!await canAccessIndividual(req.user,photo.individual_id))return res.status(403).json({error:"forbidden"});if(!reason||reason.length>1000)return res.status(400).json({error:"review_reason_required"});const id=randomId();await db.query("INSERT INTO annotation_review_requests(id,photo_id,field_key,reason,created_by) VALUES($1,$2,$3,$4,$5)",[id,req.params.id,fieldKey,reason,req.user.id]);await audit(req.user,"review_requested","photo",req.params.id,{fieldKey,reason},req);res.status(201).json({request:{id,photoId:req.params.id,fieldKey,reason,status:"pending"}});}catch(e){next(e);}});
